    n = len(A)
    det = Fraction(1)
    for i in range(n):
        for j in range(i + 1, n):
            factor = Fraction(A[j][i], A[i][i])
            for k in range(i + 1, n):
                A[j][k] -= factor * A[i][k]
        det *= A[i][i]
    return det

